import{_ as a,o,c as i,a7 as t}from"./chunks/framework.FWlv_suP.js";const u=JSON.parse('{"title":"ARFlix Privacy Policy","description":"Official Privacy Policy for ARFlix.","frontmatter":{"title":"ARFlix Privacy Policy","description":"Official Privacy Policy for ARFlix.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"privacy/arflix.md","filePath":"privacy/arflix.md"}'),r={name:"privacy/arflix.md"};function n(s,e,l,d,c,p){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="privacy-policy-for-arflix" tabindex="-1">Privacy Policy for ARFlix <a class="header-anchor" href="#privacy-policy-for-arflix" aria-label="Permalink to &quot;Privacy Policy for ARFlix&quot;">​</a></h1><p><strong>Effective Date:</strong> August 1, 2026<br><strong>Last Updated:</strong> August 1, 2026</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>ARFlix is a movie and television discovery application developed by <strong>Anand Raja</strong>. It displays information obtained from third-party data services and does not host or stream movies or television programmes.</p><p>ARFlix does not include advertising, developer-operated analytics, or a developer-operated user-account service.</p><h2 id="information-stored-on-your-device" tabindex="-1">Information Stored on Your Device <a class="header-anchor" href="#information-stored-on-your-device" aria-label="Permalink to &quot;Information Stored on Your Device&quot;">​</a></h2><p>ARFlix stores a small local preference record in localStorage. It can include a user-entered display name, a SHA-1 hash used to remember successful local content-gate access, and the family-content preference. The entered password is hashed on the device and is not stored as plain text or sent to an ARFlix server.</p><p>This local gate controls whether the interface can request and show adult-marked content. It is not a personal online account, identity-verification system, parental-control guarantee, or secure storage mechanism.</p><p>The browser or Android WebView may also retain ordinary cache, navigation, and site data under platform controls.</p><h2 id="tmdb-requests" tabindex="-1">TMDb Requests <a class="header-anchor" href="#tmdb-requests" aria-label="Permalink to &quot;TMDb Requests&quot;">​</a></h2><p>ARFlix sends requests to The Movie Database (TMDb) to load trending, popular, now-playing, on-air, genre, search, movie, television, person, cast, image, video, certification, similar-title, and watch-provider information.</p><p>Search text, selected filters, title or person identifiers, page numbers, content-filter choices, and standard connection information such as IP address, user agent, request time, and requested resource can be processed by TMDb. Movie posters, backdrops, and profile images are loaded from TMDb&#39;s image service. TMDb&#39;s processing is governed by the <a href="https://www.themoviedb.org/privacy-policy" target="_blank" rel="noreferrer">TMDb Privacy Policy</a>.</p><p>This product uses the TMDb API but is not endorsed or certified by TMDb.</p><h2 id="ar-collection-and-google-sheets" tabindex="-1">AR Collection and Google Sheets <a class="header-anchor" href="#ar-collection-and-google-sheets" aria-label="Permalink to &quot;AR Collection and Google Sheets&quot;">​</a></h2><p>The AR Collection page reads a developer-curated public Google Sheet containing title, type, platform, language, category, adult-content marker, comment, and optional TMDb identifier fields. ARFlix does not write your information to that sheet.</p><p>Google may receive standard connection information when the sheet is requested. Google&#39;s processing is governed by the <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Google Privacy Policy</a>.</p><h2 id="external-links-and-media" tabindex="-1">External Links and Media <a class="header-anchor" href="#external-links-and-media" aria-label="Permalink to &quot;External Links and Media&quot;">​</a></h2><p>ARFlix can open YouTube trailers or videos, IMDb pages, watch-provider information, and other external destinations after your action. Those services receive the requested URL and normal connection information and apply their own privacy practices. ARFlix does not control their content, availability, cookies, accounts, subscriptions, or charges.</p><p>Watch-provider data is informational. ARFlix does not verify availability, sell subscriptions, play protected content, or transmit viewing activity to a developer server.</p><h2 id="image-saving" tabindex="-1">Image Saving <a class="header-anchor" href="#image-saving" aria-label="Permalink to &quot;Image Saving&quot;">​</a></h2><p>When you choose to save a poster or image, ARFlix may download it from its source or through the <code>wsrv.nl</code> image proxy and save it to the Android media library, including the <strong>Pictures/ARFlix</strong> folder where supported. The image host or proxy can receive the image URL and standard connection information. Android manages the saved copy outside ARFlix app storage.</p><h2 id="links-and-clipboard" tabindex="-1">Links and Clipboard <a class="header-anchor" href="#links-and-clipboard" aria-label="Permalink to &quot;Links and Clipboard&quot;">​</a></h2><p>ARFlix can create public web links and Android deep links to app pages. When you choose a copy action, the selected link is placed on the clipboard. Other apps and the operating system may access clipboard content according to platform rules.</p><h2 id="information-collected-by-the-developer" tabindex="-1">Information Collected by the Developer <a class="header-anchor" href="#information-collected-by-the-developer" aria-label="Permalink to &quot;Information Collected by the Developer&quot;">​</a></h2><p>ARFlix has no developer-operated endpoint that receives search history, viewed titles, credentials, content-filter choices, device identifiers, or usage telemetry. ARFlix does not sell user information.</p><p>If you contact the developer by email, the developer receives the information you voluntarily provide and uses it to respond to your request.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>ARFlix uses internet access to retrieve TMDb data and images, the public AR Collection sheet, trailers, and external pages. Android media-library access is used to save an image only after you request it, subject to Android version and platform storage behavior. Deep-link handling opens supported ARFlix links.</p><p>The reviewed app does not require location, contacts, phone, SMS, microphone, camera, or call-log permissions.</p><h2 id="retention-and-deletion" tabindex="-1">Retention and Deletion <a class="header-anchor" href="#retention-and-deletion" aria-label="Permalink to &quot;Retention and Deletion&quot;">​</a></h2><p>Local login and family-content preferences remain until you log out, replace them, clear ARFlix app/site storage, or uninstall the app. Logging out removes the stored user record but retains the family preference.</p><p>Clearing app data or uninstalling does not remove images saved to the Android media library. Delete those images separately using a gallery or file manager. Third parties control their own logs and retention under their privacy policies.</p><p>There is no developer-operated ARFlix user account or cloud profile to delete by email.</p><h2 id="children-s-privacy" tabindex="-1">Children&#39;s Privacy <a class="header-anchor" href="#children-s-privacy" aria-label="Permalink to &quot;Children&#39;s Privacy&quot;">​</a></h2><p>ARFlix does not knowingly collect children&#39;s personal information through a developer-operated service. The local family filter is a convenience and is not a substitute for device-level parental controls or adult supervision.</p><h2 id="changes-to-this-policy" tabindex="-1">Changes to This Policy <a class="header-anchor" href="#changes-to-this-policy" aria-label="Permalink to &quot;Changes to This Policy&quot;">​</a></h2><p>This policy may be updated when ARFlix&#39;s features or data practices change. The dates above will be revised when an updated policy is published.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><ul><li><strong>Developer:</strong> Anand Raja</li><li><strong>Email:</strong> <a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></li></ul>',39)])])}const m=a(r,[["render",n]]);export{u as __pageData,m as default};
